/**
 * @jest-environment node
 *
 * Request sources and sinks of the Kotlin stack: Spring Boot, Ktor, http4k, Micronaut, Quarkus (JAX-RS / Panache), Javalin, Vert.x, Koin, Exposed,
 * Hibernate / JPA, Compose Multiplatform and desktop apps -- with coroutines (suspend, withContext, launch, flow), extension functions, data classes,
 * nullability (`?.`, `!!`, `?:`), lambdas and Java interop. Each vulnerable case ("rule") must be reported; each "!rule" case is the safe counterpart
 * (bound parameter, numeric type, allow-list, constant) that must stay quiet.
 */
import { runScan } from "@/lib/scanner";
import { ensureTaintEngines } from "@/lib/engineWarmup";
jest.setTimeout(300_000);
beforeAll(async () => { await ensureTaintEngines(); }, 120_000);
const ids = (name: string, content: string) =>
  runScan({ repo: "x", pr_number: 1, commit_sha: "a", branch: "main", files: [{ path: `t/${name}`, content }] })
    .files[0].indicators.filter(i => i.line != null && i.id !== "ai-model-attribution").map(i => i.id);
const SP = (body: string, sig = `@RequestParam q: String`) => `import org.springframework.web.bind.annotation.*\nimport org.springframework.jdbc.core.JdbcTemplate\nimport javax.persistence.EntityManager\nimport java.io.*\nimport java.net.*\n\n@RestController\nclass C(private val jdbc: JdbcTemplate, private val em: EntityManager) {\n    @GetMapping("/a")\n    fun a(${sig}): String {\n${body}\n        return "ok"\n    }\n}\n`;
const KT = (body: string) => `import io.ktor.client.*\nimport io.ktor.client.request.*\nimport io.ktor.client.engine.cio.*\nimport io.ktor.server.application.*\nimport io.ktor.server.request.*\nimport io.ktor.server.response.*\nimport io.ktor.server.routing.*\nimport java.io.File\n\nfun Application.module() {\n    routing {\n${body}\n    }\n}\n`;
